import '../extensions/string_extensions.dart';

/// Templates for the files generated by `thunder feature` in BLoC and Cubit
/// projects (flutter_bloc + get_it + go_router).
class BlocStrings {
  // create singleton for BlocStrings
  static final BlocStrings instance = BlocStrings._internal();

  factory BlocStrings() => instance;

  BlocStrings._internal();

  String _title(String featureName) => featureName.words
      .map((w) => w.substring(0, 1).toUpperCase() + w.substring(1))
      .join(' ');

  /// `<feature>_state.dart` (part of the bloc / cubit file).
  String state(String featureName, {required bool cubit}) {
    final className = featureName.toDartClassName();
    final snake = featureName.toSnakeCase();
    return '''
part of '${snake}_${cubit ? 'cubit' : 'bloc'}.dart';

class ${className}State {
  final ApiResult apiResult;

  const ${className}State({required this.apiResult});
}
''';
  }

  /// `<feature>_event.dart` (part of the bloc file).
  String event(String featureName) {
    final className = featureName.toDartClassName();
    return '''
part of '${featureName.toSnakeCase()}_bloc.dart';

sealed class ${className}Event {}

/// Loads (or reloads) the data of the page.
final class ${className}Started extends ${className}Event {}
''';
  }

  /// `<feature>_bloc.dart`.
  String bloc(String featureName, {required String packageName}) {
    final className = featureName.toDartClassName();
    final snake = featureName.toSnakeCase();
    final repoField = '${className}Repo'.lowerCaseFirstLetter();
    return '''
import 'package:flutter_bloc/flutter_bloc.dart';

import 'package:$packageName/app/repositories/${snake}_repo.dart';
import 'package:$packageName/core/networking/api_result.dart';
import 'package:$packageName/core/networking/enums_networking.dart';

part '${snake}_event.dart';
part '${snake}_state.dart';

class ${className}Bloc extends Bloc<${className}Event, ${className}State> {
  final ${className}Repo $repoField;

  ${className}Bloc({required this.$repoField}) : super(${className}State(apiResult: ApiResult())) {
    on<${className}Started>(_onStarted);
  }

  Future<void> _onStarted(${className}Started event, Emitter<${className}State> emit) async {
    emit(${className}State(apiResult: ApiResult(apiCallStatus: ApiCallStatus.loading)));

    final result = await $repoField.get${className}Data();
    result.handelRequest(
      success: (result) {
        // TODO: convert result.data to your model
      },
      error: (result) {
        // TODO: handle the error (result.message)
      },
    );

    emit(${className}State(apiResult: result));
  }
}
''';
  }

  /// `<feature>_cubit.dart`.
  String cubit(String featureName, {required String packageName}) {
    final className = featureName.toDartClassName();
    final snake = featureName.toSnakeCase();
    final repoField = '${className}Repo'.lowerCaseFirstLetter();
    return '''
import 'package:flutter_bloc/flutter_bloc.dart';

import 'package:$packageName/app/repositories/${snake}_repo.dart';
import 'package:$packageName/core/networking/api_result.dart';
import 'package:$packageName/core/networking/enums_networking.dart';

part '${snake}_state.dart';

class ${className}Cubit extends Cubit<${className}State> {
  final ${className}Repo $repoField;

  ${className}Cubit({required this.$repoField}) : super(${className}State(apiResult: ApiResult()));

  /// Loads (or reloads) the data of the page.
  Future<void> getData() async {
    emit(${className}State(apiResult: ApiResult(apiCallStatus: ApiCallStatus.loading)));

    final result = await $repoField.get${className}Data();
    result.handelRequest(
      success: (result) {
        // TODO: convert result.data to your model
      },
      error: (result) {
        // TODO: handle the error (result.message)
      },
    );

    emit(${className}State(apiResult: result));
  }
}
''';
  }

  /// `<feature>_view.dart` with BlocProvider + BlocBuilder.
  String view(String featureName,
      {required String packageName, required bool cubit}) {
    final className = featureName.toDartClassName();
    final snake = featureName.toSnakeCase();
    final kind = cubit ? 'Cubit' : 'Bloc';
    final folder = cubit ? 'cubit' : 'bloc';
    final title = _title(featureName).escapeForDartString();
    final create = cubit
        ? 'sl<${className}Cubit>()..getData()'
        : 'sl<${className}Bloc>()..add(${className}Started())';
    return '''
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

import 'package:$packageName/core/di/injection.dart';
import 'package:$packageName/core/networking/enums_networking.dart';
import 'package:$packageName/helper/widgets/custom_widgets/custom_text.dart';

import '$folder/${snake}_$folder.dart';

class ${className}View extends StatelessWidget {
  const ${className}View({super.key});

  @override
  Widget build(BuildContext context) {
    return BlocProvider(
      create: (_) => $create,
      child: Scaffold(
        appBar: AppBar(title: const CustomText(txt: '$title')),
        body: BlocBuilder<$className$kind, ${className}State>(
          builder: (context, state) {
            final apiResult = state.apiResult;
            return switch (apiResult.apiCallStatus) {
              ApiCallStatus.loading => const Center(child: CircularProgressIndicator()),
              ApiCallStatus.error => Center(
                  child: CustomText(txt: apiResult.message ?? 'Something went wrong'),
                ),
              ApiCallStatus.empty => const Center(child: CustomText(txt: 'No data yet')),
              _ => const Center(child: CustomText(txt: '$title')),
            };
          },
        ),
      ),
    );
  }
}
''';
  }
}
